/* ═══════════════════════════════════════════════════════
   MUZZLE FLASH — position over bore center (face-on = dead center)
   In SVG coords (320×320 viewBox): bore center = (160, 162)
   We compute screen position from SVG bounding rect.
═══════════════════════════════════════════════════════ */
const muzzEl  = document.getElementById('muzzleFlash');
const smokeEl = document.getElementById('smokeEl');

function posMuzzle() {
    const svgEl   = document.getElementById('gunSvg');
    const svgRect = svgEl.getBoundingClientRect();
    const wrapRect= document.getElementById('gunWrap').getBoundingClientRect();
    const sx = svgRect.width  / 320;   // viewBox width=320
    const sy = svgRect.height / 320;   // viewBox height=320
    // bore center in viewBox: (160, 162)
    const mx = svgRect.left - wrapRect.left + 160 * sx;
    const my = svgRect.top  - wrapRect.top  + 162 * sy;
    muzzEl.style.left  = mx + 'px';
    muzzEl.style.top   = my + 'px';
    smokeEl.style.left = mx + 'px';
    smokeEl.style.top  = my + 'px';
}

