            width:300px!important;height:280px!important;
            display:block;border-radius:8px;
            /* subtle vignette to blend into dark background */
            mask-image:radial-gradient(ellipse 88% 88% at 50% 50%,#000 55%,transparent 100%);
            -webkit-mask-image:radial-gradient(ellipse 88% 88% at 50% 50%,#000 55%,transparent 100%);
        }

        /* ── Card ── */
        .card{
            background:var(--card);border:1px solid var(--border);border-radius:20px;
            padding:20px 20px 16px;width:100%;
            box-shadow:0 20px 60px rgba(0,0,0,.75),inset 0 1px 0 rgba(255,255,255,.04);
            display:flex;flex-direction:column;align-items:center;gap:14px;
        }
        .card.shake{animation:shake .45s ease}
        .card.sglow {animation:sglow  .8s ease}
        @keyframes shake{
            0%,100%{transform:translate(0,0)}
            15%{transform:translate(-7px,3px)}30%{transform:translate(7px,-3px)}
            50%{transform:translate(-5px,4px)}70%{transform:translate(5px,-3px)}85%{transform:translate(-3px,2px)}
        }
        @keyframes sglow{
            0%,100%{box-shadow:0 20px 60px rgba(0,0,0,.75),inset 0 1px 0 rgba(255,255,255,.04)}
            45%    {box-shadow:0 20px 60px rgba(0,0,0,.75),0 0 40px rgba(46,204,113,.2),inset 0 1px 0 rgba(255,255,255,.04)}
        }
        .divider{width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--b2) 30%,var(--b2) 70%,transparent)}
        .status{
            height:28px;display:flex;align-items:center;justify-content:center;
            font-size:.86rem;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;
            color:var(--gold);text-shadow:0 0 12px rgba(240,180,41,.3);transition:color .3s,text-shadow .3s;
        }
        .status.danger{color:var(--red);text-shadow:0 0 18px rgba(231,76,60,.65);animation:pulseRed .45s infinite alternate}
        .status.safe  {color:var(--green);text-shadow:0 0 14px rgba(46,204,113,.5)}
        .status.idle  {color:var(--dim);text-shadow:none}
        @keyframes pulseRed{to{opacity:.5}}
        .btn-group{display:flex;gap:12px;width:100%}
        .btn{
            flex:1;padding:14px 10px;font-family:'Bebas Neue',sans-serif;font-size:1.25rem;letter-spacing:2px;
            border:1px solid transparent;border-radius:10px;cursor:pointer;
            transition:transform .12s,box-shadow .12s;position:relative;overflow:hidden;color:#fff;
        }
        .btn::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.07) 0%,transparent 55%);border-radius:inherit;pointer-events:none}
        .btn-spin{
            background:linear-gradient(170deg,#1d7db8,#1a5f8c 55%,#153f60);
            border-color:rgba(52,152,219,.25);box-shadow:0 4px 16px rgba(25,80,120,.55),inset 0 1px 0 rgba(255,255,255,.09);
        }
        .btn-spin:hover:not(:disabled){transform:translateY(-2px);box-shadow:0 7px 22px rgba(52,152,219,.4),inset 0 1px 0 rgba(255,255,255,.09)}
        .btn-shoot{
            background:linear-gradient(170deg,#bf3a2a,#962020 55%,#6e1515);
            border-color:rgba(192,57,43,.3);box-shadow:0 4px 16px rgba(140,30,20,.55),inset 0 1px 0 rgba(255,255,255,.07);
        }
        .btn-shoot:hover:not(:disabled){transform:translateY(-2px);box-shadow:0 7px 22px rgba(231,76,60,.45),inset 0 1px 0 rgba(255,255,255,.07)}
        .btn:active:not(:disabled){transform:translateY(1px)!important}
        .btn:disabled{background:rgba(255,255,255,.035)!important;border-color:var(--border)!important;color:var(--dim)!important;box-shadow:none!important;transform:none!important;cursor:not-allowed}
        .bottom{width:100%;display:flex;flex-direction:column;gap:12px}
        .odds-row{width:100%;display:flex;flex-direction:column;gap:5px}
        .odds-header{display:flex;justify-content:space-between;font-size:.65rem;letter-spacing:2px;text-transform:uppercase;color:var(--dim)}
        .odds-val{font-family:'Bebas Neue',sans-serif;font-size:.82rem;color:var(--text)}
        .odds-track{width:100%;height:5px;background:rgba(255,255,255,.04);border-radius:99px;overflow:hidden;border:1px solid var(--border)}
        .odds-fill{height:100%;background:linear-gradient(90deg,var(--green),var(--gold) 65%,var(--red));border-radius:99px;transition:width .45s cubic-bezier(.4,0,.2,1);width:83.33%}
        .stats{display:flex;gap:9px;justify-content:center}
        .stat-pill{background:var(--card2);border:1px solid var(--border);border-radius:99px;padding:6px 15px;display:flex;align-items:center;gap:6px;font-size:.72rem;color:var(--dim)}
        .sval{font-family:'Bebas Neue',sans-serif;font-size:1rem;letter-spacing:1px;color:var(--text)}
        .history{display:flex;gap:5px;justify-content:center;min-height:11px}
        .hdot{width:9px;height:9px;border-radius:50%;background:var(--b2)}
        .hdot.s{background:var(--green);box-shadow:0 0 5px rgba(46,204,113,.6)}
        .hdot.d{background:var(--red);  box-shadow:0 0 5px rgba(231,76,60,.6)}
        .hdot.new{animation:pop .22s cubic-bezier(.34,1.56,.64,1)}
        @keyframes pop{from{transform:scale(0)}to{transform:scale(1)}}
    </style>
</head>
<body>
<canvas id="particles"></canvas>
<div id="bloodOverlay"></div>
<div id="flashOverlay"></div>

<div class="wrapper">
    <div class="title">RUSSIAN ROULETTE</div>
    <div class="tagline">How lucky are you?</div>

    <!-- ── 3D Gun ── -->
    <div class="gun-scene">
        <div id="gunWrap">
            <div id="muzzleFlash"></div>
            <div id="smokeEl"></div>
            <!-- Three.js renders into this container -->
            <div id="threeContainer" style="width:300px;height:280px;position:relative;"></div>
        </div>
    </div>

    <!-- ── Card ── -->
    <div class="card" id="card">
        <div class="status idle" id="statusEl">SPIN TO BEGIN</div>
        <div class="btn-group">
            <button class="btn btn-spin"  id="spinBtn">⟳  SPIN</button>
            <button class="btn btn-shoot" id="shootBtn" disabled>FIRE  🔫</button>
        </div>
        <div class="divider"></div>
        <div class="bottom">
            <div class="odds-row">
                <div class="odds-header">
                    <span>Survival Odds</span>
                    <span class="odds-val" id="oddsVal">5 in 6</span>
                </div>
                <div class="odds-track"><div class="odds-fill" id="oddsFill"></div></div>
            </div>
            <div class="stats">
                <div class="stat-pill">💀 <span class="sval" id="svCount">0</span></div>
                <div class="stat-pill">🔄 <span class="sval" id="spCount">0</span></div>
                <div class="stat-pill">🔥 <span class="sval" id="stCount">0</span></div>
            </div>
            <div class="history" id="history"></div>
        </div>
    </div>
</div>

<script>
/* ═══════════════════════════════════════════════════════════════
   THREE.JS 3D REVOLVER
   Camera: looking straight down the barrel (front-facing view).
   The gun points toward the camera — barrel axis along +Z.
   Camera sits at Z+ looking toward Z- (into the muzzle).
═══════════════════════════════════════════════════════════════ */

const threeContainer = document.getElementById('threeContainer');

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x07090c);
// Soft vignette fog
