<body>
<canvas id="particles"></canvas>
<div id="bloodOverlay"></div>
<div id="flashOverlay"></div>

<div class="wrapper">
    <div class="title">RUSSIAN ROULETTE</div>
    <div class="tagline">How lucky are you?</div>

    <!-- ── 3D Gun ── -->
    <div class="gun-scene">
        <div id="gunWrap">
            <div id="muzzleFlash"></div>
            <div id="smokeEl"></div>
            <!-- Three.js renders into this container -->
            <div id="threeContainer" style="width:300px;height:280px;position:relative;"></div>
        </div>
    </div>

    <!-- ── Card ── -->
    <div class="card" id="card">
        <div class="status idle" id="statusEl">SPIN TO BEGIN</div>
        <div class="btn-group">
            <button class="btn btn-spin"  id="spinBtn">⟳  SPIN</button>
            <button class="btn btn-shoot" id="shootBtn" disabled>FIRE  🔫</button>
        </div>
        <div class="divider"></div>
        <div class="bottom">
            <div class="odds-row">
                <div class="odds-header">
                    <span>Survival Odds</span>
                    <span class="odds-val" id="oddsVal">5 in 6</span>
                </div>
                <div class="odds-track"><div class="odds-fill" id="oddsFill"></div></div>
            </div>
            <div class="stats">
                <div class="stat-pill">💀 <span class="sval" id="svCount">0</span></div>
                <div class="stat-pill">🔄 <span class="sval" id="spCount">0</span></div>
                <div class="stat-pill">🔥 <span class="sval" id="stCount">0</span></div>
            </div>
            <div class="history" id="history"></div>
        </div>
    </div>
</div>

<script>
/* ═══════════════════════════════════════════════════════════════
   THREE.JS 3D REVOLVER
   Camera: looking straight down the barrel (front-facing view).
   The gun points toward the camera — barrel axis along +Z.
   Camera sits at Z+ looking toward Z- (into the muzzle).
═══════════════════════════════════════════════════════════════ */

const threeContainer = document.getElementById('threeContainer');

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x07090c);
// Soft vignette fog
scene.fog = new THREE.FogExp2(0x07090c, 0.18);

// Camera — positioned in FRONT of the gun, looking down the barrel
// Gun barrel axis is along world Z. Camera at +Z, looking toward -Z.
// FOV tight (38°) to give telephoto close-up feel like the photo.
const W = 300, H = 280;
const camera = new THREE.PerspectiveCamera(38, W / H, 0.05, 50);
// Sit right in front of the muzzle, slightly above center
// barrel is at y≈0.35, so we look from y=0.38, z=+3.2
camera.position.set(0, 0.34, 3.2);
camera.lookAt(0, 0.34, 0); // look toward the bore

// Renderer — fits in gunWrap
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(W, H);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
renderer.domElement.id = 'threeCanvas';
threeContainer.appendChild(renderer.domElement);

/* ── LIGHTING ──
   Key from above-left (brightens barrel top + cylinder rim).
   Fill from right (shows side detail).
   Rim from behind (edge-lights the frame silhouette).
   Strong front ambient so the bore is faintly visible inside. */
const ambient = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambient);

// Key — upper-left, like the reference photo
const keyLight = new THREE.DirectionalLight(0xd0e8ff, 3.2);
keyLight.position.set(-3, 6, 4);
keyLight.castShadow = true;
scene.add(keyLight);

// Fill — right side, warmer
const fillLight = new THREE.DirectionalLight(0xffd8a0, 1.2);
fillLight.position.set(4, 1, 3);
scene.add(fillLight);

// Rim — from behind the gun (Z-), rim-lights the silhouette edges
const rimLight = new THREE.DirectionalLight(0x6090c0, 1.8);
rimLight.position.set(0, 3, -6);
scene.add(rimLight);

// Muzzle flash point light (activated on BANG)
const flashLight = new THREE.PointLight(0xff8800, 0, 6);
flashLight.position.set(0, 0.35, 2.8);
scene.add(flashLight);

/* ── MATERIALS ── */
// Blued steel frame
const matFrame = new THREE.MeshStandardMaterial({
    color: 0x1a2230, metalness: 0.92, roughness: 0.30,
});
// Cylinder — slightly lighter, higher contrast to show chambers
const matCyl = new THREE.MeshStandardMaterial({
    color: 0x384858, metalness: 0.96, roughness: 0.18,
});
// Dark recesses / bore
const matDark = new THREE.MeshStandardMaterial({
    color: 0x080c12, metalness: 0.7, roughness: 0.6,
});
// Brass cartridge
const matBrass = new THREE.MeshStandardMaterial({
    color: 0xc49020, metalness: 0.98, roughness: 0.15,
});
// Bullet primer (silver)
const matPrimer = new THREE.MeshStandardMaterial({
    color: 0x8090a0, metalness: 0.95, roughness: 0.25,
});
// Wood grip
const matWood = new THREE.MeshStandardMaterial({
    color: 0x3a1808, roughness: 0.70, metalness: 0.04,
});
// Muzzle flash cone
const matFlash = new THREE.MeshBasicMaterial({
    color: 0xffe080, transparent: true, opacity: 0,
});

/* ── GUN ROOT GROUP ── */
const gunRoot = new THREE.Group();
// Tilt gun slightly so barrel center is easy to aim camera at
// No rotation needed — we orient gun so barrel runs along Z axis.
// Barrel tip at Z≈-4.8, muzzle (toward camera) at Z≈-1.0
// Camera at Z=3.2 looking at Z=0 → sees straight into the bore.
scene.add(gunRoot);

/* ═══════════════════════════════════
   FRAME COMPONENTS
   (Same geometry as file.txt but tweaked
    for front-facing camera framing)
═══════════════════════════════════ */

// Rear frame / recoil shield
const recoilShield = new THREE.Mesh(
    new THREE.BoxGeometry(0.50, 1.05, 0.35), matFrame);
recoilShield.position.set(0, 0.05, 0.72);
gunRoot.add(recoilShield);

// Top strap — runs above the cylinder window
const topStrap = new THREE.Mesh(
    new THREE.BoxGeometry(0.42, 0.17, 1.65), matFrame);
topStrap.position.set(0, 0.63, -0.05);
gunRoot.add(topStrap);

// Bottom frame / crane housing — below cylinder
const bottomFrame = new THREE.Mesh(
    new THREE.BoxGeometry(0.42, 0.19, 1.50), matFrame);
bottomFrame.position.set(0, -0.52, -0.05);
gunRoot.add(bottomFrame);

// Front frame junction — connects frame to barrel
const frontFrame = new THREE.Mesh(
    new THREE.BoxGeometry(0.44, 1.00, 0.30), matFrame);
frontFrame.position.set(0, 0.05, -0.88);
gunRoot.add(frontFrame);

// Rear sight housing
const rearSight = new THREE.Mesh(
    new THREE.BoxGeometry(0.10, 0.09, 0.22), matFrame);
rearSight.position.set(0, 0.74, 0.60);
gunRoot.add(rearSight);

/* ═══════════════════════════════════
   CYLINDER ASSEMBLY
   The star of the show — centered in the frame window.
   Rotated about Z axis for spinning.
═══════════════════════════════════ */
const cylinderGroup = new THREE.Group();
cylinderGroup.position.set(0, 0.05, -0.07);
gunRoot.add(cylinderGroup);

// Main cylinder drum
const cylBody = new THREE.Mesh(
    new THREE.CylinderGeometry(0.62, 0.62, 1.28, 36), matCyl);
cylBody.rotation.x = Math.PI / 2;
cylinderGroup.add(cylBody);

// Central extractor pin
const axisPin = new THREE.Mesh(
    new THREE.CylinderGeometry(0.11, 0.11, 1.45, 16), matFrame);
axisPin.rotation.x = Math.PI / 2;
cylinderGroup.add(axisPin);

// 6 chambers: flutes + brass cartridge faces
const CHAMBER_R = 0.365;
for (let i = 0; i < 6; i++) {
    const angle = (i * Math.PI) / 3;
    const cx = Math.cos(angle) * CHAMBER_R;
    const cy = Math.sin(angle) * CHAMBER_R;

    // Bore tunnel through cylinder (dark)
    const boreTunnel = new THREE.Mesh(
        new THREE.CylinderGeometry(0.12, 0.12, 1.32, 16), matDark);
    boreTunnel.rotation.x = Math.PI / 2;
    boreTunnel.position.set(cx, cy, 0);
    cylinderGroup.add(boreTunnel);

    // Brass cartridge rim (back face, toward viewer in front-facing camera)
    // In front-facing view the FRONT face of cylinder is toward camera.
    // z = +0.62 is the front face (closest to camera at +Z).
    const cartridge = new THREE.Mesh(
        new THREE.CylinderGeometry(0.115, 0.115, 0.055, 16), matBrass);
    cartridge.rotation.x = Math.PI / 2;
    cartridge.position.set(cx, cy, 0.645);
    cylinderGroup.add(cartridge);

    // Primer dot
    const primer = new THREE.Mesh(
        new THREE.CylinderGeometry(0.042, 0.042, 0.062, 12), matPrimer);
    primer.rotation.x = Math.PI / 2;
    primer.position.set(cx, cy, 0.648);
    cylinderGroup.add(primer);

    // Flute groove between chambers
    const fluteAngle = angle + Math.PI / 6;
    const flute = new THREE.Mesh(
        new THREE.CylinderGeometry(0.12, 0.12, 0.90, 12), matDark);
    flute.rotation.x = Math.PI / 2;
    flute.position.set(
        Math.cos(fluteAngle) * 0.59,
        Math.sin(fluteAngle) * 0.59,
        -0.05
    );
    cylinderGroup.add(flute);
}

/* ═══════════════════════════════════
   BARREL
   Long cylinder running along Z axis away from camera.
   Muzzle end closest to camera (toward +Z), breach end at -Z.
   Barrel center Y = 0.35 (above cylinder center).
═══════════════════════════════════ */
const BARREL_LEN = 3.0;
// barrel center Z: front face at Z≈-1.0, runs to Z≈-(1.0+barrelLen)
const barrelZ = -1.0 - BARREL_LEN / 2;

const barrel = new THREE.Mesh(
    new THREE.CylinderGeometry(0.24, 0.25, BARREL_LEN, 28), matFrame);
barrel.rotation.x = Math.PI / 2;
barrel.position.set(0, 0.35, barrelZ);
gunRoot.add(barrel);

// Underlug / ejector shroud below barrel
const underlug = new THREE.Mesh(
    new THREE.BoxGeometry(0.22, 0.33, BARREL_LEN), matFrame);
underlug.position.set(0, 0.10, barrelZ);
gunRoot.add(underlug);

// Ejector rod (silver)
const ejectorRod = new THREE.Mesh(
    new THREE.CylinderGeometry(0.055, 0.055, 0.65, 12), matCyl);
ejectorRod.rotation.x = Math.PI / 2;
ejectorRod.position.set(0, 0.05, -1.35);
gunRoot.add(ejectorRod);

// Muzzle crown ring (at the FRONT, closest to camera)
// The muzzle is what the camera stares into!
// Muzzle Z position = front face of barrel = -1.0 + small offset
const muzzleZ = -1.0;
const muzzleCrown = new THREE.Mesh(
    new THREE.TorusGeometry(0.245, 0.025, 12, 32), matCyl);
muzzleCrown.rotation.x = Math.PI / 2; // orient ring to face +Z (camera)
muzzleCrown.position.set(0, 0.35, muzzleZ);
gunRoot.add(muzzleCrown);

// Bore hole at muzzle (very dark, looks into the barrel)
const muzzleBore = new THREE.Mesh(
    new THREE.CylinderGeometry(0.135, 0.135, 0.12, 20), matDark);
muzzleBore.rotation.x = Math.PI / 2;
muzzleBore.position.set(0, 0.35, muzzleZ - 0.04);
gunRoot.add(muzzleBore);

// Front sight blade
const frontSight = new THREE.Mesh(
    new THREE.BoxGeometry(0.07, 0.22, 0.30), matFrame);
frontSight.position.set(0, 0.68, -BARREL_LEN - 0.75);
gunRoot.add(frontSight);

// Red front sight insert
const redInsert = new THREE.Mesh(
    new THREE.BoxGeometry(0.075, 0.08, 0.10),
    new THREE.MeshBasicMaterial({ color: 0xef4444 }));
redInsert.position.set(0, 0.72, -BARREL_LEN - 0.80);
gunRoot.add(redInsert);

/* ═══════════════════════════════════
   TRIGGER GUARD + TRIGGER
═══════════════════════════════════ */
const guardGeo = new THREE.TorusGeometry(0.48, 0.05, 10, 24, Math.PI * 0.85);
const guard = new THREE.Mesh(guardGeo, matFrame);
guard.position.set(0, -0.58, 0.12);
guard.rotation.y = Math.PI / 2;
guard.rotation.x = 0.35;
gunRoot.add(guard);

const triggerPivot = new THREE.Group();
triggerPivot.position.set(0, -0.38, 0.22);
gunRoot.add(triggerPivot);

const triggerBlade = new THREE.Mesh(
    new THREE.BoxGeometry(0.075, 0.43, 0.14), matCyl);
triggerBlade.position.set(0, -0.15, -0.05);
triggerBlade.rotation.x = 0.4;
triggerPivot.add(triggerBlade);

/* ═══════════════════════════════════
   HAMMER
═══════════════════════════════════ */
const hammerPivot = new THREE.Group();
hammerPivot.position.set(0, 0.42, 0.82);
gunRoot.add(hammerPivot);

const hammerBody = new THREE.Mesh(
    new THREE.BoxGeometry(0.13, 0.45, 0.23), matCyl);
hammerBody.position.set(0, 0.16, 0.06);
hammerBody.rotation.x = -0.45;
hammerPivot.add(hammerBody);

const hammerSpur = new THREE.Mesh(
    new THREE.BoxGeometry(0.15, 0.10, 0.17), matCyl);
hammerSpur.position.set(0, 0.32, 0.15);
hammerPivot.add(hammerSpur);

/* ═══════════════════════════════════
   GRIP
═══════════════════════════════════ */
const gripGroup = new THREE.Group();
gripGroup.position.set(0, -0.42, 0.95);
gripGroup.rotation.x = -0.48;

const gripMain = new THREE.Mesh(
    new THREE.BoxGeometry(0.55, 1.85, 0.78), matWood);
gripMain.position.set(0, -0.7, 0);
gripGroup.add(gripMain);

const medallion = new THREE.Mesh(
    new THREE.CylinderGeometry(0.08, 0.08, 0.60, 16), matBrass);
medallion.rotation.z = Math.PI / 2;
medallion.position.set(0, -0.45, 0);
gripGroup.add(medallion);

const gripButt = new THREE.Mesh(
    new THREE.SphereGeometry(0.38, 14, 14), matFrame);
gripButt.scale.set(0.70, 0.30, 1.05);
gripButt.position.set(0, -1.65, 0.05);
gripGroup.add(gripButt);

gunRoot.add(gripGroup);

/* ═══════════════════════════════════
   MUZZLE FLASH CONE
   Points toward camera (+Z)
═══════════════════════════════════ */
const flashMesh = new THREE.Mesh(
    new THREE.ConeGeometry(0.52, 2.0, 8), matFlash);
// ConeGeometry points up (+Y), rotate to point toward +Z (camera)
flashMesh.rotation.x = Math.PI / 2;
flashMesh.position.set(0, 0.35, muzzleZ + 1.2); // in front of muzzle toward camera
gunRoot.add(flashMesh);

/* ═══════════════════════════════════
   CAMERA POSITIONING
   We want to see straight down the bore.
   Barrel at Y=0.35, muzzle at Z≈-1.0.
   Camera at Z=+3.2, Y=0.35 → looks straight in.
   Small Y offset up for dramatic "looking down" feel.
═══════════════════════════════════ */
// (already set above — recalibrate here after building model)
camera.position.set(0, 0.48, 3.0);
camera.lookAt(0, 0.35, 0);

/* ═══════════════════════════════════
   RENDER LOOP
═══════════════════════════════════ */
const animState = {
    recoilRot: 0,
    recoilZ: 0,
    cylSpinVel: 0,       // current spin velocity (rad/s)
    cylTargetRot: 0,     // target rotation for settle
    isSpinning: false,
    isFiring: false,
    breathT: 0,
};

function renderLoop() {
    requestAnimationFrame(renderLoop);

    const now = performance.now();
    const delta = 0.016; // ~60fps target

    // Spring recoil recovery
    animState.recoilRot += (0 - animState.recoilRot) * 14 * delta;
    animState.recoilZ   += (0 - animState.recoilZ)   * 14 * delta;
    gunRoot.rotation.x = animState.recoilRot;
    gunRoot.position.z = animState.recoilZ;

    // Subtle idle breathing
    if (!animState.isFiring && !animState.isSpinning) {
        animState.breathT += delta;
        gunRoot.position.y = Math.sin(animState.breathT * 0.9) * 0.012;
    }

    renderer.render(scene, camera);
}
renderLoop();

/* ═══════════════════════════════════
   3D ANIMATION HELPERS
═══════════════════════════════════ */

// Animate cylinder spinning: fast spin then settle to a specific final rotation
function animCylSpin(totalExtraRot, duration, onDone) {
    const start = performance.now();
    const startRot = cylinderGroup.rotation.z;
    const endRot = startRot + totalExtraRot;

    function tick(now) {
        const p = Math.min((now - start) / duration, 1);
        // Ease: fast start, slow deceleration (like spinning and slowing)
        const e = 1 - Math.pow(1 - p, 3);
        cylinderGroup.rotation.z = startRot + (endRot - startRot) * e;
        if (p < 1) {
            requestAnimationFrame(tick);
        } else {
            cylinderGroup.rotation.z = endRot;
            if (onDone) onDone();
        }
    }
    requestAnimationFrame(tick);
}

// Trigger pull animation: pull back → release → reset
function animTriggerPull(onFire) {
    const start = performance.now();
    const pullDur = 200;
    const startRot = triggerPivot.rotation.x;

    function tick(now) {
        const p = Math.min((now - start) / pullDur, 1);
        const s = p * p * (3 - 2 * p);
        triggerPivot.rotation.x = startRot - s * 0.45;
        hammerPivot.rotation.x  = -s * 0.80;
        if (p < 1) {
            requestAnimationFrame(tick);
        } else {
            // Fire!
            hammerPivot.rotation.x = 0.15; // snap forward
            triggerPivot.rotation.x = 0;
            if (onFire) onFire();
            // Reset hammer
            setTimeout(() => { hammerPivot.rotation.x = 0; }, 180);
        }
    }
    requestAnimationFrame(tick);
}

// Trigger dry-fire: smaller motion
function animDryfire(onDone) {
    const start = performance.now();
    function tick(now) {
        const p = Math.min((now - start) / 140, 1);
        const s = p < 0.5 ? 2*p*p : 1-Math.pow(-2*p+2,2)/2;
        triggerPivot.rotation.x = -s * 0.22;
        hammerPivot.rotation.x  = -s * 0.35;
        if (p < 1) {
            requestAnimationFrame(tick);
        } else {
            triggerPivot.rotation.x = 0;
            hammerPivot.rotation.x  = 0;
            if (onDone) onDone();
        }
    }
    requestAnimationFrame(tick);
}

function triggerMuzzleFlash3D() {
    matFlash.opacity = 1.0;
    flashLight.intensity = 10.0;
    flashMesh.scale.set(
        1 + Math.random() * 0.4,
        1 + Math.random() * 0.4,
        1 + Math.random() * 0.3
    );
    setTimeout(() => {
        matFlash.opacity = 0;
        flashLight.intensity = 0;
    }, 55);
}

/* ═══════════════════════════════════════════════════════════════
   AUDIO
═══════════════════════════════════════════════════════════════ */
const AC = new (window.AudioContext || window.webkitAudioContext)();
const resumeAC = () => { if (AC.state === 'suspended') AC.resume(); };

const playRatchet = () => {
    resumeAC(); const t = AC.currentTime;
    const o = AC.createOscillator(), f = AC.createBiquadFilter(), g = AC.createGain();
    o.type = 'triangle';
    o.frequency.setValueAtTime(1400 + Math.random()*200, t);
    o.frequency.exponentialRampToValueAtTime(350, t+.025);
    f.type = 'bandpass'; f.frequency.value = 2200; f.Q.value = 5;
    g.gain.setValueAtTime(.25, t); g.gain.linearRampToValueAtTime(.001, t+.025);
    o.connect(f); f.connect(g); g.connect(AC.destination);
    o.start(t); o.stop(t+.025);
};
const playThud = () => {
    resumeAC(); const t = AC.currentTime;
    const o = AC.createOscillator(), g = AC.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(190, t);
    o.frequency.exponentialRampToValueAtTime(48, t+.09);
    g.gain.setValueAtTime(.5, t); g.gain.linearRampToValueAtTime(.001, t+.09);
    o.connect(g); g.connect(AC.destination); o.start(t); o.stop(t+.09);
};
const playTrigger = () => {
    resumeAC(); const t = AC.currentTime;
    [[1800,400,.04,'sine',0,.38],[140,38,.07,'triangle',.03,.48]].forEach(([f1,f2,d,tp,dl,v]) => {
        const o = AC.createOscillator(), g = AC.createGain();
        o.type = tp;
        o.frequency.setValueAtTime(f1, t+dl);
        o.frequency.exponentialRampToValueAtTime(f2, t+dl+d);
        g.gain.setValueAtTime(v, t+dl); g.gain.linearRampToValueAtTime(.001, t+dl+d);
        o.connect(g); g.connect(AC.destination); o.start(t+dl); o.stop(t+dl+d);
    });
};
const playEmpty = () => {
    resumeAC(); const t = AC.currentTime;
    const o = AC.createOscillator(), g = AC.createGain();
    o.type = 'square';
    o.frequency.setValueAtTime(700, t);
    o.frequency.exponentialRampToValueAtTime(220, t+.06);
    g.gain.setValueAtTime(.15, t); g.gain.linearRampToValueAtTime(.001, t+.06);
    o.connect(g); g.connect(AC.destination); o.start(t); o.stop(t+.06);
};
const playBang = () => {
    resumeAC(); const t = AC.currentTime, dur = 2;
    const buf = AC.createBuffer(1, AC.sampleRate*dur, AC.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random()*2-1;
    const ns = AC.createBufferSource(); ns.buffer = buf;
    const fl = AC.createBiquadFilter(); fl.type='lowpass';
    fl.frequency.setValueAtTime(1100, t);
    fl.frequency.exponentialRampToValueAtTime(55, t+dur);
    const gn = AC.createGain();
    gn.gain.setValueAtTime(1, t); gn.gain.exponentialRampToValueAtTime(.001, t+dur);
    ns.connect(fl); fl.connect(gn); gn.connect(AC.destination); ns.start(t);
    const sb = AC.createOscillator(), sg = AC.createGain();
    sb.type='sine';
    sb.frequency.setValueAtTime(110, t); sb.frequency.exponentialRampToValueAtTime(28, t+.35);
    sg.gain.setValueAtTime(1, t); sg.gain.linearRampToValueAtTime(.001, t+.35);
    sb.connect(sg); sg.connect(AC.destination); sb.start(t); sb.stop(t+.35);
};

/* ═══════════════════════════════════════════════════════════════
   PARTICLES (background canvas, unchanged)
═══════════════════════════════════════════════════════════════ */
const cv = document.getElementById('particles'), ctx = cv.getContext('2d');
let W2, H2;
const resize = () => { W2 = cv.width = window.innerWidth; H2 = cv.height = window.innerHeight; };
resize(); window.addEventListener('resize', resize);
const allP = [];
class Particle {
    constructor(x,y,col) {
        this.x=x; this.y=y; this.col=col;
        this.vx=(Math.random()-.5)*7; this.vy=(Math.random()-1.1)*8;
        this.r=Math.random()*4+1.5; this.life=1;
    }
    step() { this.vx*=.97; this.vy+=.16; this.x+=this.vx; this.y+=this.vy; this.life-=.02; }
    draw() {
        ctx.save(); ctx.globalAlpha=Math.max(0,this.life);
        ctx.shadowColor=this.col; ctx.shadowBlur=7;
        ctx.fillStyle=this.col; ctx.beginPath();
        ctx.arc(this.x,this.y,this.r,0,Math.PI*2); ctx.fill(); ctx.restore();
    }
}
function burst(x,y,col,n=35) { for(let i=0;i<n;i++) allP.push(new Particle(x,y,col)); }
const embers = Array.from({length:22}, () => {
    const e = { reset() {
        this.x=Math.random()*window.innerWidth; this.y=window.innerHeight+8;
        this.r=Math.random()*1.6+.3; this.vx=(Math.random()-.5)*.4;
        this.vy=-(Math.random()*.5+.2); this.alpha=Math.random()*.3+.07; this.life=1;
    }};
    e.reset(); e.y=Math.random()*window.innerHeight; return e;
});
(function pLoop() {
    ctx.clearRect(0,0,W2,H2);
    for (let i=allP.length-1;i>=0;i--) {
        allP[i].step(); allP[i].draw();
        if (allP[i].life<=0) allP.splice(i,1);
    }
    for (const e of embers) {
        e.x+=e.vx; e.y+=e.vy; e.life-=.0025;
        ctx.save(); ctx.globalAlpha=e.alpha*e.life;
        ctx.fillStyle='#e74c3c'; ctx.shadowColor='#e74c3c'; ctx.shadowBlur=5;
        ctx.beginPath(); ctx.arc(e.x,e.y,e.r,0,Math.PI*2); ctx.fill(); ctx.restore();
        if (e.life<=0) e.reset();
    }
    requestAnimationFrame(pLoop);
})();

/* ═══════════════════════════════════════════════════════════════
   DOM REFS + GAME STATE
═══════════════════════════════════════════════════════════════ */
const spinBtn   = document.getElementById('spinBtn');
const shootBtn  = document.getElementById('shootBtn');
const statusEl  = document.getElementById('statusEl');
const svCountEl = document.getElementById('svCount');
const spCountEl = document.getElementById('spCount');
const stCountEl = document.getElementById('stCount');
const oddsFill  = document.getElementById('oddsFill');
const oddsVal   = document.getElementById('oddsVal');
const historyEl = document.getElementById('history');
const card      = document.getElementById('card');
const bloodOv   = document.getElementById('bloodOverlay');
const flashOv   = document.getElementById('flashOverlay');
const muzzEl    = document.getElementById('muzzleFlash');
const smokeEl   = document.getElementById('smokeEl');
const gunWrap   = document.getElementById('gunWrap');

let bulletPos = Math.floor(Math.random()*6), currentPos = 0;
let isSpun = false, survives = 0, spins = 0, streak = 0, histArr = [];

const setStatus = (t,c='') => { statusEl.textContent=t; statusEl.className='status '+c; };
const setOdds   = (n,d)    => { oddsFill.style.width=((n/d)*100)+'%'; oddsVal.textContent=n+' in '+d; };

function addDot(s) {
    histArr.push(s); if(histArr.length>14) histArr.shift();
    historyEl.innerHTML='';
    histArr.forEach((v,i) => {
        const dot=document.createElement('div');
        dot.className='hdot '+(v?'s':'d')+(i===histArr.length-1?' new':'');
        historyEl.appendChild(dot);
    });
}

function screenFlash() {
    flashOv.style.opacity='.9';
    setTimeout(()=>{ flashOv.style.opacity='0'; }, 70);
}

function animGunCss(t) {
    gunWrap.classList.remove('recoil','dryfire'); void gunWrap.offsetWidth;
    gunWrap.classList.add(t);
    setTimeout(()=>gunWrap.classList.remove(t), t==='recoil'?400:220);
}

function triggerMuzzleCSS() {
    muzzEl.classList.remove('bang'); void muzzEl.offsetWidth; muzzEl.classList.add('bang');
    setTimeout(()=>{ smokeEl.classList.remove('puff'); void smokeEl.offsetWidth; smokeEl.classList.add('puff'); }, 100);
}

/* ═══════════════════════════════════════════════════════════════
   SPIN BUTTON
═══════════════════════════════════════════════════════════════ */
spinBtn.addEventListener('click', () => {
    if (spinBtn.disabled) return;
    spinBtn.disabled = true;
    shootBtn.disabled = true;
    bloodOv.classList.remove('active');
    setStatus('SPINNING...', '');
    animState.isSpinning = true;

    bulletPos = Math.floor(Math.random()*6);

    // Total rotation: 3–5 full turns + random chamber offset
    const fullTurns = (Math.floor(Math.random()*3) + 3) * Math.PI * 2;
    const chamberOffset = Math.floor(Math.random()*6) * (Math.PI / 3);
    const totalRot = fullTurns + chamberOffset;
    const spinDur  = 1300;

    // Play ratchet clicks during spin
    let clicks = 0;
    const maxClicks = 22;
    const ratchetInterval = setInterval(() => {
        if (clicks++ < maxClicks) playRatchet();
        else clearInterval(ratchetInterval);
    }, spinDur / maxClicks);

    animCylSpin(totalRot, spinDur, () => {
        playThud();
        animState.isSpinning = false;
        currentPos = Math.round(
            ((2 * Math.PI - (cylinderGroup.rotation.z % (2 * Math.PI))) % (2 * Math.PI))
            / (Math.PI / 3)
        ) % 6;
        isSpun = true;
        spinBtn.disabled = false;
        shootBtn.disabled = false;
        setStatus('PULL THE TRIGGER', '');
        spins++;
        spCountEl.textContent = spins;
        setOdds(5, 6);
    });
});

/* ═══════════════════════════════════════════════════════════════
   SHOOT BUTTON
═══════════════════════════════════════════════════════════════ */
shootBtn.addEventListener('click', () => {
    if (!isSpun || shootBtn.disabled) return;
    spinBtn.disabled  = true;
    shootBtn.disabled = true;
    setStatus('...', '');
    playTrigger();
    animState.isFiring = true;

    setTimeout(() => {
        if (currentPos === bulletPos) {
            /* ══ BANG ══ */
            animTriggerPull(() => {
                playBang();
                screenFlash();
                animGunCss('recoil');
                triggerMuzzleFlash3D();
                triggerMuzzleCSS();

                // 3D recoil
                animState.recoilRot = 0.38;
                animState.recoilZ   = 0.25;

                setTimeout(()=>{ bloodOv.classList.add('active'); }, 55);
                card.classList.add('shake');
                setTimeout(()=>card.classList.remove('shake'), 500);
                setStatus('BANG', 'danger');

                const r = card.getBoundingClientRect();
                burst(W2/2, H2/2, '#c0392b', 85);
                burst(W2/2, H2/2, '#e74c3c', 50);
                burst(W2/2, H2/2, '#ff7070', 20);

                addDot(false); streak=0; stCountEl.textContent=streak;
                svCountEl.textContent=survives;
                isSpun=false;
                animState.isFiring = false;
                spinBtn.disabled=false;
                spinBtn.textContent='⟳  TRY AGAIN';
                setOdds(0,1);
            });
        } else {
            /* ══ CLICK — empty ══ */
            animDryfire(() => {
                playEmpty();
                animGunCss('dryfire');
                card.classList.add('sglow');
                setTimeout(()=>card.classList.remove('sglow'), 900);
                setStatus('CLICK — SURVIVED', 'safe');

                const r = card.getBoundingClientRect();
                burst(r.left+r.width/2, r.top+60, '#2ecc71', 28);
                burst(r.left+r.width/2, r.top+60, '#27ae60', 18);

                survives++; streak++;
                svCountEl.textContent=survives;
                stCountEl.textContent=streak;
                addDot(true);

                isSpun = false;
                // Advance cylinder one click
                animCylSpin(Math.PI/3, 300, null);
                currentPos = (currentPos+1)%6;

                playThud();
                animState.isFiring = false;
                spinBtn.disabled = false;
                shootBtn.disabled = true;
                spinBtn.textContent = '⟳  SPIN';
                setOdds(4,5);
            });
        }
    }, 480);
});

setOdds(5, 6);
</script>
</body>
</html>

