const threeContainer = document.getElementById('threeContainer');

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x07090c);
scene.fog = new THREE.FogExp2(0x07090c, 0.032);

// Renderer — fills the gunWrap container, sized dynamically
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.domElement.id = 'threeCanvas';
threeContainer.appendChild(renderer.domElement);

// Size renderer to fill its container
function resizeRenderer() {
    const w = threeContainer.clientWidth;
    const h = threeContainer.clientHeight;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
}

// Camera — proper 3/4 view from file.txt, slightly tweaked for the layout
// Gun sits at origin. Camera above-right-front looking down at the cylinder.
const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
// Position: front-right, elevated — shows barrel going left, cylinder facing viewer
// Based on file.txt: camera.position.set(3.4, 1.4, 3.8)
// Tweaked: pull back a bit more so full gun is visible
camera.position.set(3.2, 1.6, 3.6);
camera.lookAt(0, 0.1, -0.2);

