/* ── Two-column layout ── */
.layout{
    position:relative;z-index:10;
    display:flex;flex-direction:row;align-items:center;
    width:100vw;height:100vh;
}

/* LEFT / CENTER — gun takes ~60% */
.gun-col{
    flex:1 1 0;
    display:flex;align-items:center;justify-content:center;
    height:100%;
    position:relative;
}

/* RIGHT PANEL */
.ui-col{
    flex:0 0 320px;
    display:flex;flex-direction:column;
    justify-content:center;
    align-items:stretch;
    height:100%;
    padding:24px 28px 24px 8px;
    gap:14px;
}

.title{
    font-family:'Bebas Neue',sans-serif;font-size:clamp(2rem,3.2vw,2.8rem);
    letter-spacing:8px;color:var(--red);
    text-shadow:0 0 40px rgba(231,76,60,.6),0 0 80px rgba(231,76,60,.15);
    line-height:1;user-select:none;
}
.tagline{font-size:.60rem;letter-spacing:4px;text-transform:uppercase;color:var(--dim);margin-top:2px}

/* ── 3D Gun wrapper ── */
#gunWrap{
    position:relative;
    width:min(58vw,700px);
    height:min(88vh,700px);
}
#gunWrap.recoil {animation:recoil  .35s cubic-bezier(.1,.7,.3,1) forwards}
#gunWrap.dryfire{animation:dryfire .18s ease-out forwards}
@keyframes recoil{
    0%  {transform:translate(0,0) scale(1) rotate(0deg)}
    20% {transform:translate(0px,14px) scale(.97) rotate(1deg)}
    50% {transform:translate(0px,-6px) scale(1.01) rotate(-.5deg)}
    100%{transform:translate(0,0) scale(1) rotate(0deg)}
}
@keyframes dryfire{
    0%  {transform:translate(0,0) scale(1)}
    50% {transform:translate(0,4px) scale(.99)}
    100%{transform:translate(0,0) scale(1)}
}

/* Muzzle flash — at barrel muzzle position in the 3/4 view (front-left area) */
#muzzleFlash{
    position:absolute;left:34%;top:46%;
    transform:translate(-50%,-50%);
    width:0;height:0;border-radius:50%;pointer-events:none;opacity:0;z-index:20;
}
#muzzleFlash.bang{animation:muzzBang .28s ease-out forwards}
@keyframes muzzBang{
    0%  {opacity:1;width:0;height:0;box-shadow:0 0 0 0 #fff,0 0 0 0 #ffe066,0 0 0 0 rgba(231,76,60,.9)}
    30% {opacity:1;width:120px;height:120px;margin:-60px;box-shadow:0 0 50px 18px #fff,0 0 90px 36px #ffe066,0 0 140px 50px rgba(231,76,60,.6)}
    100%{opacity:0;width:160px;height:160px;margin:-80px;box-shadow:0 0 0 0 transparent,0 0 0 0 transparent,0 0 0 0 transparent}
}
#smokeEl{
    position:absolute;left:34%;top:46%;transform:translate(-50%,-50%);
    width:12px;height:12px;border-radius:50%;background:rgba(180,200,220,.5);
    filter:blur(6px);opacity:0;pointer-events:none;z-index:19;
}
#smokeEl.puff{animation:smokeDrift 1.4s ease-out forwards}
@keyframes smokeDrift{
    0%  {opacity:.6;transform:translate(-50%,-50%) scale(1)}
    100%{opacity:0;transform:translate(-50%,-130px) scale(7)}
}

#threeCanvas{
    width:100%!important;height:100%!important;
    display:block;
}

/* ── Card ── */
.card{
    background:var(--card);border:1px solid var(--border);border-radius:20px;
    padding:20px 20px 16px;width:100%;
    box-shadow:0 20px 60px rgba(0,0,0,.75),inset 0 1px 0 rgba(255,255,255,.04);
    display:flex;flex-direction:column;align-items:center;gap:14px;
}

