// Smoothly reset camera to the good 3/4 view
function resetCamera() {
    const startPos = camera.position.clone();
    const endPos   = new THREE.Vector3(4.2, 2.0, 4.8);
    const startTgt = controls.target.clone();
    const endTgt   = new THREE.Vector3(0, 0.05, -0.8);
    const t0 = performance.now();
    const dur = 600;
    (function camTick(now) {
        const p = Math.min((now - t0) / dur, 1);
        const e = 1 - Math.pow(1 - p, 3); // ease-out cubic
        camera.position.lerpVectors(startPos, endPos, e);
        controls.target.lerpVectors(startTgt, endTgt, e);
        controls.update();
        if (p < 1) requestAnimationFrame(camTick);
    })(performance.now());
}

