PRESETS.forEach(hex => {
    const s = document.createElement('div');
    s.className = 'bgp';
    s.style.background = hex;
    s.title = hex;
    s.addEventListener('click', () => { applyBg(hex); presetsEl.classList.remove('open'); });
    presetsEl.appendChild(s);
});
