colorInput2.addEventListener('input', () => applyBg(colorInput2.value));

function applyBg(hex) {
    // Update CSS custom property & body background
    document.documentElement.style.setProperty('--bg', hex);
    document.body.style.background = hex;

    // Update Three.js scene background + fog
    const c = new THREE.Color(hex);
    scene.background = c;
    scene.fog = new THREE.FogExp2(c.getHex(), 0.032);

    // Update swatch
    swatchEl.style.background = hex;
    colorInput2.value = hex;

    // Update particles canvas background (it's transparent, body color shows through)
    // — handled by body background change above
}

