input.newStr:
/* ═══════════════════════════════════
   BARREL
   Barrel sits just above the cylinder, aligned with
   the top of the frame. Cylinder center Y=0.05, radius=0.62
   → cylinder top = 0.67. Barrel radius ~0.22, so barrel
   center Y = 0.67 + 0.22 + 0.04 gap = 0.93... that's too high.
   Actually on a real revolver the barrel axis aligns with the
   top chamber of the cylinder. Top chamber offset = CHAMBER_R = 0.365
   above cylinder center → barrel Y = 0.05 + 0.365 = 0.415.
   Use 0.42 so barrel lines up with the top chamber bore.
═══════════════════════════════════ */
const BARREL_LEN = 3.0;
const barrelZ = -1.0 - BARREL_LEN / 2;
const BARREL_Y = 0.42; // aligns with top chamber of cylinder

const barrel = new THREE.Mesh(
    new THREE.CylinderGeometry(0.22, 0.23, BARREL_LEN, 28), matFrame);
barrel.rotation.x = Math.PI / 2;
barrel.position.set(0, BARREL_Y, barrelZ);
gunRoot.add(barrel);

// Underlug / ejector shroud — hangs below barrel
const underlug = new THREE.Mesh(
    new THREE.BoxGeometry(0.20, 0.28, BARREL_LEN), matFrame);
